import formatMoney from './format-money';
import { getLogger } from '~/lib/log';
import { storeKeys } from '../mixins/base-listing-mixin';

const log = getLogger('productRecommendation');

export default function productRecommendation(config = {}, url = null) {
  const base = storeKeys(config);

  return {
    ...base,
    products: [],
    currentProductId: config.productId || null,
    ProductRecommendationService: null,
    moneyFormatter: formatMoney,

    async init() {
      if (url !== null) {
        this.initLazyLoad(url.url);
        return;
      }

      const parentProductId = `gid://shopify/Product/${this.currentProductId}`;
      const factory = this.createStorefrontFactory();
      this.ProductRecommendationService = factory.createProductRecommendationService();
      const recommendedProductData = await this.ProductRecommendationService.getRecommendedProducts(parentProductId);
      this.products = recommendedProductData;
    },

    initLazyLoad(url) {
      const productRecommendationsSection = document.querySelector('.recommended-product');
      if (!productRecommendationsSection) {
        return;
      }

      fetch(url)
        .then((response) => response.text())
        .then((text) => {
          const html = document.createElement('div');
          html.innerHTML = text;
          const recommendations = html.querySelector('.recommended-product');

          if (recommendations && recommendations.innerHTML.trim().length) {
            productRecommendationsSection.innerHTML = recommendations.innerHTML;
          }
        })
        .catch((e) => log.error(e));
    },
  };
}

